import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"47、【困】 坎下兌上","description":"橫渠易說 - 47、【困】 坎下兌上","frontmatter":{"title":"47、【困】 坎下兌上","description":"橫渠易說 - 47、【困】 坎下兌上"},"headers":[],"relativePath":"classics/hengqu/049.md","filePath":"classics/hengqu/049.md"}'),l={name:"classics/hengqu/049.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_47、【困】-坎下兌上" tabindex="-1">47、【困】 坎下兌上 <a class="header-anchor" href="#_47、【困】-坎下兌上" aria-label="Permalink to “47、【困】 坎下兌上”">​</a></h1><h3 id="彖曰-困-剛掩也。險以說-困而不失其所亨-其唯君子乎-貞大人吉-以剛中也-有言不信-尚口乃窮也。" tabindex="-1">彖曰：困，剛掩也。險以說，困而不失其所亨，其唯君子乎!“貞大人吉”，以剛中也；“有言不信”，尚口乃窮也。 <a class="header-anchor" href="#彖曰-困-剛掩也。險以說-困而不失其所亨-其唯君子乎-貞大人吉-以剛中也-有言不信-尚口乃窮也。" aria-label="Permalink to “彖曰：困，剛掩也。險以說，困而不失其所亨，其唯君子乎!“貞大人吉”，以剛中也；“有言不信”，尚口乃窮也。”">​</a></h3><h3 id="象曰-澤無水-困-君子以致命遂志。" tabindex="-1">象曰：澤無水，困，君子以致命遂志。 <a class="header-anchor" href="#象曰-澤無水-困-君子以致命遂志。" aria-label="Permalink to “象曰：澤無水，困，君子以致命遂志。”">​</a></h3><p>升而不己必困，故受之以困。困於險下，柔不自振，非窮而能亨，致命遂志者也。</p><h3 id="初六-臀困於株木-入於幽谷-三歲不覿。-象曰-入於幽谷-幽不明也。" tabindex="-1">初六，臀困於株木，入於幽谷，三歲不覿。 象曰：“入於幽谷”，幽不明也。 <a class="header-anchor" href="#初六-臀困於株木-入於幽谷-三歲不覿。-象曰-入於幽谷-幽不明也。" aria-label="Permalink to “初六，臀困於株木，入於幽谷，三歲不覿。 象曰：“入於幽谷”，幽不明也。”">​</a></h3><p>處困者正乃無咎，居非得中，故幽而不明。</p><h3 id="九二-困於酒食-朱紱方來-利用享祀-徵兇-無咎。-象曰-困於酒食-中有慶也。" tabindex="-1">九二，困於酒食，朱紱方來，利用享祀，徵兇，無咎。 象曰：“困於酒食”，中有慶也。 <a class="header-anchor" href="#九二-困於酒食-朱紱方來-利用享祀-徵兇-無咎。-象曰-困於酒食-中有慶也。" aria-label="Permalink to “九二，困於酒食，朱紱方來，利用享祀，徵兇，無咎。 象曰：“困於酒食”，中有慶也。”">​</a></h3><p>困危之際，物思所附。九二以剛居中正，大人之吉，上下交說，不施聰明，美物方至，然未可有為，故以祭則吉，以徵則兇，徵雖或兇，於義無咎。際一作世。</p><h3 id="六三-困於石-據於蒺藜-入於其宮不見其妻-兇。-象曰-據於蒺藜-乘剛也-入於其宮不見其妻-不祥也。" tabindex="-1">六三，困於石，據於蒺藜，入於其宮不見其妻，兇。 象曰：“據於蒺藜”，乘剛也；“入於其宮不見其妻”，不祥也。 <a class="header-anchor" href="#六三-困於石-據於蒺藜-入於其宮不見其妻-兇。-象曰-據於蒺藜-乘剛也-入於其宮不見其妻-不祥也。" aria-label="Permalink to “六三，困於石，據於蒺藜，入於其宮不見其妻，兇。 象曰：“據於蒺藜”，乘剛也；“入於其宮不見其妻”，不祥也。”">​</a></h3><h3 id="九四-來徐徐-困於金車-吝有終。-象曰-來徐徐-志在下也-雖不當位-有與也。" tabindex="-1">九四，來徐徐，困於金車，吝有終。 象曰：“來徐徐”，志在下也，雖不當位，有與也。 <a class="header-anchor" href="#九四-來徐徐-困於金車-吝有終。-象曰-來徐徐-志在下也-雖不當位-有與也。" aria-label="Permalink to “九四，來徐徐，困於金車，吝有終。 象曰：“來徐徐”，志在下也，雖不當位，有與也。”">​</a></h3><p>心有偏系，吝也，以陽履柔，故有終。</p><h3 id="九五-劓刖-困於赤紱-乃徐有說-利用祭祀。-象曰-劓刖-志未得也-乃徐有說-以中直也-利用祭祀-受福也。" tabindex="-1">九五，劓刖，困於赤紱，乃徐有說，利用祭祀。 象曰：“劓刖”，志未得也；“乃徐有說”，以中直也；“利用祭祀”，受福也。 <a class="header-anchor" href="#九五-劓刖-困於赤紱-乃徐有說-利用祭祀。-象曰-劓刖-志未得也-乃徐有說-以中直也-利用祭祀-受福也。" aria-label="Permalink to “九五，劓刖，困於赤紱，乃徐有說，利用祭祀。 象曰：“劓刖”，志未得也；“乃徐有說”，以中直也；“利用祭祀”，受福也。”">​</a></h3><p>以陽居陽，處困以剛，威怒以求物之來，是反為赤紱所困者也，與九二之義反矣。苟能徐以俟之，乃心有說，故曰“乃徐有說”。物既自至，以事鬼神，然後福可致焉。處困用中，可以不失其守而已，故言“利用祭祀”，然非有為之時也。</p><h3 id="上六-困於葛藟-於臲卼-曰動悔有悔-徵吉。-象曰-困於葛藟-未當也-動悔有悔-吉行也。" tabindex="-1">上六，困於葛藟，於臲卼，曰動悔有悔，徵吉。 象曰：“困於葛藟”，未當也；“動悔有悔”，吉行也。 <a class="header-anchor" href="#上六-困於葛藟-於臲卼-曰動悔有悔-徵吉。-象曰-困於葛藟-未當也-動悔有悔-吉行也。" aria-label="Permalink to “上六，困於葛藟，於臲卼，曰動悔有悔，徵吉。 象曰：“困於葛藟”，未當也；“動悔有悔”，吉行也。”">​</a></h3><p>處困之極，重剛在下，不得其肆，居非所安，舉則招悔，取捨皆咎，故行然後吉。一雲：“動悔有悔”，猶雲動悔之悔也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
